#!/usr/bin/env bash
# The mutants of publish-jobs.test.sh, one per rule of the job layout. Sourced by it: it defines `mutant`, `gate_mutant`
# and the paths they use. Each mutant's second argument is Python for publish-jobs-mutate.py (see its docstring for the
# names it sees); `gate_mutant` takes a sed script for publish-gate.test.sh instead.

# shellcheck disable=SC2016,SC2154

# the suites matrix
mutant "matrix without the swift tests part" 'reject(include, lambda e: e.get("part") == "tests")'
mutant "matrix without the swift gates part" 'reject(include, lambda e: e.get("part") == "gates")'
mutant "matrix without the swift speed part" 'reject(include, lambda e: e.get("part") == "speed")'
mutant "matrix with swift as one whole entry" 'reject(include, lambda e: e.get("lang") == "swift"); include.append({"lang": "swift"})'
mutant "matrix without typescript" 'e = next(x for x in include if "typescript" in x["lang"].split()); e["lang"] = " ".join(l for l in e["lang"].split() if l != "typescript")'
mutant "matrix runs go twice" 'include.append({"lang": "go"})'
mutant "matrix with a language that has no suite" 'include.append({"lang": "cobol"})'
mutant "matrix entry with an extra key" 'include[0]["extra"] = "x"'
mutant "matrix with an exclude" 'jobs["suites"]["strategy"]["matrix"]["exclude"] = [{"lang": "cpp"}]'
mutant "matrix without fail-fast false" 'del jobs["suites"]["strategy"]["fail-fast"]'
mutant "matrix with fail-fast true" 'jobs["suites"]["strategy"]["fail-fast"] = True'
mutant "suites job without a matrix" 'del jobs["suites"]["strategy"]'
mutant "suites step without set -euo pipefail" 'sub(step_named("suites", "suite"), "run", "set -euo pipefail\n", "")'
mutant "suites step ignores the matrix language" 'step_named("suites", "suite")["env"]["SUITE"] = "go"'
mutant "suites step without the swift part" 'del step_named("suites", "suite")["env"]["PACKBIN_SWIFT_PART"]'
mutant "suites step without -e PACKBIN_SWIFT_PART" 'sub(step_named("suites", "suite"), "run", " -e PACKBIN_SWIFT_PART", "")'
mutant "suites job needs scaffold" 'jobs["suites"]["needs"] = "scaffold"'
mutant "suites job with if" 'jobs["suites"]["if"] = "github.ref == \"refs/heads/main\""'
mutant "suites step continue-on-error" 'step_named("suites", "suite")["continue-on-error"] = True'
mutant "suites job without timeout" 'del jobs["suites"]["timeout-minutes"]'
mutant "suites job removed" 'del jobs["suites"]'
mutant "suites step also in scaffold" 'jobs["scaffold"]["steps"].append(deep(step_named("suites", "suite")))'
mutant "a suite run in the ring job" 'jobs["ring"]["steps"].append({"name": "go", "run": "docker compose -f docker-compose.test.yml run --rm go"})'
mutant "cpp in two entries" 'include.append({"lang": "cpp"})'
mutant "java dropped from its shared entry" 'e = next(x for x in include if "java" in x["lang"].split()); e["lang"] = " ".join(l for l in e["lang"].split() if l != "java")'
mutant "a Swift part shares its entry" 'next(x for x in include if x.get("part") == "speed")["lang"] = "swift go"; reject(include, lambda x: x.get("lang") == "go")'
mutant "an entry that names no suite" 'include.append({"lang": " "})'
mutant "suites step stops at its first failing suite" 'sub(step_named("suites", "suite"), "run", " || failed=\"$failed $suite\"", "")'
mutant "suites step does not fail after a failed suite" 'resub(step_named("suites", "suite"), "run", r"^ *exit 1\n", "")'
mutant "suites step does not name the failed suites" 'sub(step_named("suites", "suite"), "run", "::$failed\"", "::some suites\"")'
mutant "suites step runs only the first suite of its entry" 'sub(step_named("suites", "suite"), "run", "for suite in $SUITE; do", "for suite in ${SUITE%% *}; do")'
mutant "more than 20 jobs" 'jobs.update({f"extra-{i}": deep(jobs["scaffold"]) for i in range(3)})'
mutant "an if on the suite step" 'step_named("suites", "suite")["if"] = "matrix.part != \"\""'
mutant "cache step continue-on-error" 'step_named("suites", "Swift build cache")["continue-on-error"] = True'
mutant "an if on a step that only names the cache" 'step_named("suites", "Swift image tag")["if"] = "always()"'
mutant "cache step by a tag, not a commit" 'step_named("suites", "Swift build cache")["uses"] = "actions/cache@v6"'
mutant "cache key without the image tag" 'sub(step_named("suites", "Swift build cache")["with"], "key", "${{ steps.swift-pin.outputs.tag }}-", "")'
mutant "cache key without Package.resolved" 'resub(step_named("suites", "Swift build cache")["with"], "key", r", .Package\.resolved.", "")'
mutant "cache key without run-suite.sh" 'resub(step_named("suites", "Swift build cache")["with"], "key", r", .\.github/workflows/run-suite\.sh.", "")'
mutant "cache key without the part" 'sub(step_named("suites", "Swift build cache")["with"], "key", "${{ matrix.part }}-", "")'
mutant "cache restored by a prefix" 'step_named("suites", "Swift build cache")["with"]["restore-keys"] = "swift-v2-"'
mutant "cache also on a tag run" 'resub(step_named("suites", "Swift build cache"), "if", r" && !startsWith\(.*\)", "")'
mutant "cache after the suite step" 'st = jobs["suites"]["steps"]; c = step_named("suites", "Swift build cache"); st.remove(c); st.append(c)'
mutant "cache step removed" 'drop_step("suites", "Swift build cache")'
mutant "suite step without the cache state" 'del step_named("suites", "suite")["env"]["PACKBIN_SWIFT_CACHE"]'
mutant "image tag step reads another pin" 'sub(step_named("suites", "Swift image tag"), "run", "tool-pin.sh swift", "tool-pin.sh go")'
# the publish gate jobs
mutant "readonly-gate-good group dropped" 'gate_step("publish-gate-readonly-gate-good")["run"] = "bash .github/workflows/publish-gate.test.sh --groups readonly-gate-bad"; gate_step("publish-gate-readonly-gate-bad")["run"] = "bash .github/workflows/publish-gate.test.sh --groups readonly-gate-nojava"'
mutant "readonly-gate-bad also in the good job" 'gate_step("publish-gate-readonly-gate-good")["run"] += ",readonly-gate-bad"'
mutant "readonly-gate-nojava job without the pull step" 'drop_step("publish-gate-readonly-gate-nojava", "pull images")'
mutant "readonly-gate-good job without the pull step" 'drop_step("publish-gate-readonly-gate-good", "pull images")'
mutant "readonly-gate-bad moved to the job without a pull" 'gate_step("publish-gate-readonly-gate-bad")["run"] = "bash .github/workflows/publish-gate.test.sh --groups readonly-gate-good"; gate_step("publish-gate-swift")["run"] += ",readonly-gate-bad"'
mutant "phases-rerun also in the phases job" 'gate_step("publish-gate-phases")["run"] += ",phases-rerun"'
mutant "phases-rerun job without the pull step" 'drop_step("publish-gate-phases-rerun", "pull images")'
mutant "phases-rerun dropped" 'gate_step("publish-gate-phases-rerun")["run"] = "bash .github/workflows/publish-gate.test.sh --groups phases"'
mutant "pins also in the readonly job" 'gate_step("publish-gate-readonly")["run"] += ",pins"'
mutant "pins moved to the job without a pull" 'sub(gate_step("publish-gate-rest"), "run", ",pins", ""); gate_step("publish-gate-swift")["run"] += ",pins"'
mutant "readonly group also in the phases job" 'gate_step("publish-gate-phases")["run"] = "bash .github/workflows/publish-gate.test.sh --groups phases,readonly"'
mutant "readonly-full also in the phases job" 'gate_step("publish-gate-phases")["run"] += ",readonly-full"'
mutant "swift group also in the rest job" 'gate_step("publish-gate-rest")["run"] += ",swift"'
mutant "a container group moved to the job without a pull" 'gate_step("publish-gate-readonly")["run"] = "bash .github/workflows/publish-gate.test.sh --groups gate"; gate_step("publish-gate-swift")["run"] += ",readonly"'
mutant "rest job (readonly-full) without the pull step" 'drop_step("publish-gate-rest", "pull images")'
mutant "no gate job at all" 'for n in [n for n in jobs if n.startswith("publish-gate-")]: del jobs[n]'
mutant "a group that does not exist" 'gate_step("publish-gate-rest")["run"] += ",bogus"'
mutant "the rest job names no group" 'gate_step("publish-gate-rest")["run"] = "bash .github/workflows/publish-gate.test.sh --groups ,"'
mutant "a gate job without --groups" 'gate_step("publish-gate-phases")["run"] = "bash .github/workflows/publish-gate.test.sh"'
mutant "a gate job with a flag instead of groups" 'gate_step("publish-gate-rest")["run"] = "bash .github/workflows/publish-gate.test.sh --npm"'
mutant "the gate also runs in scaffold" 'jobs["scaffold"]["steps"].append(deep(gate_step("publish-gate-rest")))'
mutant "the whole gate in the readonly job too" 'gate_step("publish-gate-readonly")["run"] = "bash .github/workflows/publish-gate.test.sh"'
mutant "the old publish-gate job is left" 'jobs["publish-gate"] = deep(jobs["publish-gate-rest"])'
mutant "readonly job without the pull step" 'drop_step("publish-gate-readonly", "pull images")'
mutant "phases job without the pull step" 'drop_step("publish-gate-phases", "pull images")'
mutant "pull step after the gate" 'jobs["publish-gate-phases"]["steps"].reverse()'
mutant "pull step without swift" 'sub(step_named("publish-gate-readonly", "pull images"), "run", " swift", "")'
mutant "phases pull without java" 'sub(step_named("publish-gate-phases", "pull images"), "run", " java", "")'
mutant "nojava pull without python" 'sub(step_named("publish-gate-readonly-gate-nojava", "pull images"), "run", " python", "")'
mutant "phases pull with swift" 'step_named("publish-gate-phases", "pull images")["run"] += " swift"'
mutant "rest pull with go" 'step_named("publish-gate-rest", "pull images")["run"] += " go"'
mutant "phases pull names java twice" 'step_named("publish-gate-phases", "pull images")["run"] += " java"'
mutant "nojava pull with java" 'step_named("publish-gate-readonly-gate-nojava", "pull images")["run"] += " java"'
mutant "a pull in the swift job, whose group starts no container" 'jobs["publish-gate-swift"]["steps"].insert(1, deep(step_named("publish-gate-phases", "pull images")))'
mutant "two pull steps in the phases job" 'jobs["publish-gate-phases"]["steps"].insert(1, deep(step_named("publish-gate-phases", "pull images")))'
mutant "gate step with if" 'gate_step("publish-gate-rest")["if"] = "github.ref == \"refs/heads/main\""'
mutant "gate step continue-on-error" 'gate_step("publish-gate-readonly")["continue-on-error"] = True'
mutant "gate job needs scaffold" 'jobs["publish-gate-phases"]["needs"] = "scaffold"'
mutant "gate job continue-on-error" 'jobs["publish-gate-rest"]["continue-on-error"] = True'
mutant "gate job without timeout" 'del jobs["publish-gate-readonly"]["timeout-minutes"]'
mutant "gate job removed" 'del jobs["publish-gate-rest"]'
gate_mutant "a new group that no job runs" 's/^gate_groups="\(.*\)"$/gate_groups="\1 extra"/'
gate_mutant "a group renamed in the list" 's/^gate_groups="\(.*\) readonly-gate-bad \(.*\)"$/gate_groups="\1 ro-gate-bad \2"/'
gate_mutant "the phases-rerun group left out of the list" 's/^gate_groups="\(.*\) phases-rerun \(.*\)"$/gate_groups="\1 \2"/'
gate_mutant "an old readonly-gate group back in the list" 's/^gate_groups="\(.*\) readonly-full"$/gate_groups="\1 readonly-gate readonly-full"/'
gate_mutant "a read-only group left out of the list" 's/^gate_groups="\(.*\) readonly-full"$/gate_groups="\1"/'
# the embedded jobs
mutant "embedded arm job removed" 'del jobs["embedded-arm"]'
mutant "embedded packages part runs the core part twice" 'jobs["embedded-esp-packages"]["steps"][1]["run"] = jobs["embedded-esp-core"]["steps"][1]["run"]'
mutant "embedded core job runs the whole ESP stage" 'sub(jobs["embedded-esp-core"]["steps"][1], "run", "host esp core", "host esp")'
mutant "embedded part runs in two jobs" 'jobs["embedded-esp-core"]["steps"][1]["run"] += "\nbash cpp/embedded/run.sh host arm"'
mutant "the unsplit embedded job is left" 'jobs["embedded"] = deep(jobs["embedded-arm"])'
mutant "an unsplit embedded run in the ring job" 'jobs["ring"]["steps"].append({"name": "embedded", "run": "bash cpp/embedded/run.sh"})'
mutant "embedded job with if" 'jobs["embedded-arm"]["if"] = "github.ref == \"refs/heads/main\""'
mutant "embedded job needs scaffold" 'jobs["embedded-esp-core"]["needs"] = "scaffold"'
mutant "embedded job continue-on-error" 'jobs["embedded-esp-packages"]["continue-on-error"] = True'
mutant "embedded job without timeout" 'del jobs["embedded-arm"]["timeout-minutes"]'
mutant "embedded run step with if" 'jobs["embedded-arm"]["steps"][1]["if"] = "always()"'
mutant "embedded run step continue-on-error" 'jobs["embedded-esp-core"]["steps"][1]["continue-on-error"] = True'
mutant "embedded part misspelled" 'sub(jobs["embedded-esp-packages"]["steps"][1], "run", "packages", "package")'
# the static checks
mutant "scaffold without the embedded parts step" 'drop_step("scaffold", "embedded parts")'
mutant "scaffold without the report columns step" 'drop_step("scaffold", "report columns")'
mutant "ring preparation test moved to ring" 'jobs["ring"]["steps"].append(step_named("scaffold", "ring preparation")); drop_step("scaffold", "ring preparation")'
mutant "scaffold without the primitive reference vectors step" 'drop_step("scaffold", "primitive reference vectors")'
mutant "scaffold without the frame mode vectors step" 'drop_step("scaffold", "frame mode vectors")'
mutant "scaffold without the message ECC vectors step" 'drop_step("scaffold", "message ECC vectors")'
mutant "scaffold without the message ECC reference bounds step" 'drop_step("scaffold", "message ECC reference bounds")'
mutant "message ECC ring self-test moved to ring" 'jobs["ring"]["steps"].append(step_named("scaffold", "message ECC ring self-test")); drop_step("scaffold", "message ECC ring self-test")'
mutant "message ECC ring dropped from ring" 'drop_step("ring", "message ECC ring")'
mutant "scaffold static check moved to ring" 'jobs["ring"]["steps"].append(step_named("scaffold", "suite runner")); drop_step("scaffold", "suite runner")'
